var DeleteLinesAction = class extends EditorAction {
	constructor() {
		super({
			id: "editor.action.deleteLines",
			label: localize2(1325, "Delete Line"),
			precondition: EditorContextKeys.writable,
			kbOpts: {
				kbExpr: EditorContextKeys.textInputFocus,
				primary: 3113,
				weight: 100
			},
			canTriggerInlineEdits: true
		});
	}
	run(_accessor, editor) {
		if (!editor.hasModel()) return;
		const ops = this._getLinesToRemove(editor);
		const model = editor.getModel();
		if (model.getLineCount() === 1 && model.getLineMaxColumn(1) === 1) return;
		let linesDeleted = 0;
		const edits = [];
		const cursorState = [];
		for (let i = 0, len = ops.length; i < len; i++) {
			const op = ops[i];
			let startLineNumber = op.startLineNumber;
			let endLineNumber = op.endLineNumber;
			let startColumn = 1;
			let endColumn = model.getLineMaxColumn(endLineNumber);
			if (endLineNumber < model.getLineCount()) {
				endLineNumber += 1;
				endColumn = 1;
			} else if (startLineNumber > 1) {
				startLineNumber -= 1;
				startColumn = model.getLineMaxColumn(startLineNumber);
			}
			edits.push(EditOperation.replace(new Selection(startLineNumber, startColumn, endLineNumber, endColumn), ""));
			cursorState.push(new Selection(startLineNumber - linesDeleted, op.positionColumn, startLineNumber - linesDeleted, op.positionColumn));
			linesDeleted += op.endLineNumber - op.startLineNumber + 1;
		}
		editor.pushUndoStop();
		editor.executeEdits(this.id, edits, cursorState);
		editor.revealAllCursors(true);
		editor.pushUndoStop();
	}
	_getLinesToRemove(editor) {
		const operations = editor.getSelections().map((s) => {
			let endLineNumber = s.endLineNumber;
			if (s.startLineNumber < s.endLineNumber && s.endColumn === 1) endLineNumber -= 1;
			return {
				startLineNumber: s.startLineNumber,
				selectionStartColumn: s.selectionStartColumn,
				endLineNumber,
				positionColumn: s.positionColumn
			};
		});
		operations.sort((a, b) => {
			if (a.startLineNumber === b.startLineNumber) return a.endLineNumber - b.endLineNumber;
			return a.startLineNumber - b.startLineNumber;
		});
		const mergedOperations = [];
		let previousOperation = operations[0];
		for (let i = 1; i < operations.length; i++) if (previousOperation.endLineNumber + 1 >= operations[i].startLineNumber) previousOperation.endLineNumber = operations[i].endLineNumber;
		else {
			mergedOperations.push(previousOperation);
			previousOperation = operations[i];
		}
		mergedOperations.push(previousOperation);
		return mergedOperations;
	}
};
