var AbstractDeleteAllToBoundaryAction = class extends EditorAction {
	run(_accessor, editor) {
		if (!editor.hasModel()) return;
		const primaryCursor = editor.getSelection();
		const rangesToDelete = this._getRangesToDelete(editor);
		const effectiveRanges = [];
		for (let i = 0, count = rangesToDelete.length - 1; i < count; i++) {
			const range = rangesToDelete[i];
			const nextRange = rangesToDelete[i + 1];
			if (Range.intersectRanges(range, nextRange) === null) effectiveRanges.push(range);
			else rangesToDelete[i + 1] = Range.plusRange(range, nextRange);
		}
		effectiveRanges.push(rangesToDelete[rangesToDelete.length - 1]);
		const endCursorState = this._getEndCursorState(primaryCursor, effectiveRanges);
		const edits = effectiveRanges.map((range) => {
			return EditOperation.replace(range, "");
		});
		editor.pushUndoStop();
		editor.executeEdits(this.id, edits, endCursorState);
		editor.pushUndoStop();
	}
};
var DeleteAllLeftAction = class extends AbstractDeleteAllToBoundaryAction {
	constructor() {
		super({
			id: "deleteAllLeft",
			label: localize2(1330, "Delete All Left"),
			precondition: EditorContextKeys.writable,
			kbOpts: {
				kbExpr: EditorContextKeys.textInputFocus,
				primary: 0,
				mac: { primary: 2049 },
				weight: 100
			},
			canTriggerInlineEdits: true
		});
	}
	_getEndCursorState(primaryCursor, rangesToDelete) {
		let endPrimaryCursor = null;
		const endCursorState = [];
		let deletedLines = 0;
		rangesToDelete.forEach((range) => {
			let endCursor;
			if (range.endColumn === 1 && deletedLines > 0) {
				const newStartLine = range.startLineNumber - deletedLines;
				endCursor = new Selection(newStartLine, range.startColumn, newStartLine, range.startColumn);
			} else endCursor = new Selection(range.startLineNumber, range.startColumn, range.startLineNumber, range.startColumn);
			deletedLines += range.endLineNumber - range.startLineNumber;
			if (range.intersectRanges(primaryCursor)) endPrimaryCursor = endCursor;
			else endCursorState.push(endCursor);
		});
		if (endPrimaryCursor) endCursorState.unshift(endPrimaryCursor);
		return endCursorState;
	}
	_getRangesToDelete(editor) {
		const selections = editor.getSelections();
		if (selections === null) return [];
		let rangesToDelete = selections;
		const model = editor.getModel();
		if (model === null) return [];
		rangesToDelete.sort(Range.compareRangesUsingStarts);
		rangesToDelete = rangesToDelete.map((selection) => {
			if (selection.isEmpty()) {
				if (selection.startColumn === 1) {
					const deleteFromLine = Math.max(1, selection.startLineNumber - 1);
					const deleteFromColumn = selection.startLineNumber === 1 ? 1 : model.getLineLength(deleteFromLine) + 1;
					return new Range(deleteFromLine, deleteFromColumn, selection.startLineNumber, 1);
				} else return new Range(selection.startLineNumber, 1, selection.startLineNumber, selection.startColumn);
			} else return new Range(selection.startLineNumber, 1, selection.endLineNumber, selection.endColumn);
		});
		return rangesToDelete;
	}
};
var DeleteAllRightAction = class extends AbstractDeleteAllToBoundaryAction {
	constructor() {
		super({
			id: "deleteAllRight",
			label: localize2(1331, "Delete All Right"),
			precondition: EditorContextKeys.writable,
			kbOpts: {
				kbExpr: EditorContextKeys.textInputFocus,
				primary: 0,
				mac: {
					primary: 297,
					secondary: [2068]
				},
				weight: 100
			},
			canTriggerInlineEdits: true
		});
	}
	_getEndCursorState(primaryCursor, rangesToDelete) {
		let endPrimaryCursor = null;
		const endCursorState = [];
		for (let i = 0, len = rangesToDelete.length, offset = 0; i < len; i++) {
			const range = rangesToDelete[i];
			const endCursor = new Selection(range.startLineNumber - offset, range.startColumn, range.startLineNumber - offset, range.startColumn);
			if (range.intersectRanges(primaryCursor)) endPrimaryCursor = endCursor;
			else endCursorState.push(endCursor);
		}
		if (endPrimaryCursor) endCursorState.unshift(endPrimaryCursor);
		return endCursorState;
	}
	_getRangesToDelete(editor) {
		const model = editor.getModel();
		if (model === null) return [];
		const selections = editor.getSelections();
		if (selections === null) return [];
		const rangesToDelete = selections.map((sel) => {
			if (sel.isEmpty()) {
				const maxColumn = model.getLineMaxColumn(sel.startLineNumber);
				if (sel.startColumn === maxColumn) return new Range(sel.startLineNumber, sel.startColumn, sel.startLineNumber + 1, 1);
				else return new Range(sel.startLineNumber, sel.startColumn, sel.startLineNumber, maxColumn);
			}
			return sel;
		});
		rangesToDelete.sort(Range.compareRangesUsingStarts);
		return rangesToDelete;
	}
};
var JoinLinesAction = class extends EditorAction {
	constructor() {
		super({
			id: "editor.action.joinLines",
			label: localize2(1332, "Join Lines"),
			precondition: EditorContextKeys.writable,
			kbOpts: {
				kbExpr: EditorContextKeys.editorTextFocus,
				primary: 0,
				mac: { primary: 296 },
				weight: 100
			},
			canTriggerInlineEdits: true
		});
	}
	run(_accessor, editor) {
		const selections = editor.getSelections();
		if (selections === null) return;
		let primaryCursor = editor.getSelection();
		if (primaryCursor === null) return;
		selections.sort(Range.compareRangesUsingStarts);
		const reducedSelections = [];
		const lastSelection = selections.reduce((previousValue, currentValue) => {
			if (previousValue.isEmpty()) {
				if (previousValue.endLineNumber === currentValue.startLineNumber) {
					if (primaryCursor.equalsSelection(previousValue)) primaryCursor = currentValue;
					return currentValue;
				}
				if (currentValue.startLineNumber > previousValue.endLineNumber + 1) {
					reducedSelections.push(previousValue);
					return currentValue;
				} else return new Selection(previousValue.startLineNumber, previousValue.startColumn, currentValue.endLineNumber, currentValue.endColumn);
			} else if (currentValue.startLineNumber > previousValue.endLineNumber) {
				reducedSelections.push(previousValue);
				return currentValue;
			} else return new Selection(previousValue.startLineNumber, previousValue.startColumn, currentValue.endLineNumber, currentValue.endColumn);
		});
		reducedSelections.push(lastSelection);
		const model = editor.getModel();
		if (model === null) return;
		const edits = [];
		const endCursorState = [];
		let endPrimaryCursor = primaryCursor;
		let lineOffset = 0;
		for (let i = 0, len = reducedSelections.length; i < len; i++) {
			const selection = reducedSelections[i];
			const startLineNumber = selection.startLineNumber;
			const startColumn = 1;
			let columnDeltaOffset = 0;
			let endLineNumber, endColumn;
			const selectionEndPositionOffset = model.getLineLength(selection.endLineNumber) - selection.endColumn;
			if (selection.isEmpty() || selection.startLineNumber === selection.endLineNumber) {
				const position = selection.getStartPosition();
				if (position.lineNumber < model.getLineCount()) {
					endLineNumber = startLineNumber + 1;
					endColumn = model.getLineMaxColumn(endLineNumber);
				} else {
					endLineNumber = position.lineNumber;
					endColumn = model.getLineMaxColumn(position.lineNumber);
				}
			} else {
				endLineNumber = selection.endLineNumber;
				endColumn = model.getLineMaxColumn(endLineNumber);
			}
			let trimmedLinesContent = model.getLineContent(startLineNumber);
			for (let i = startLineNumber + 1; i <= endLineNumber; i++) {
				const lineText = model.getLineContent(i);
				const firstNonWhitespaceIdx = model.getLineFirstNonWhitespaceColumn(i);
				if (firstNonWhitespaceIdx >= 1) {
					let insertSpace = true;
					if (trimmedLinesContent === "") insertSpace = false;
					if (insertSpace && (trimmedLinesContent.charAt(trimmedLinesContent.length - 1) === " " || trimmedLinesContent.charAt(trimmedLinesContent.length - 1) === "	")) {
						insertSpace = false;
						trimmedLinesContent = trimmedLinesContent.replace(/[\s\uFEFF\xA0]+$/g, " ");
					}
					const lineTextWithoutIndent = lineText.substr(firstNonWhitespaceIdx - 1);
					trimmedLinesContent += (insertSpace ? " " : "") + lineTextWithoutIndent;
					if (insertSpace) columnDeltaOffset = lineTextWithoutIndent.length + 1;
					else columnDeltaOffset = lineTextWithoutIndent.length;
				} else columnDeltaOffset = 0;
			}
			const deleteSelection = new Range(startLineNumber, startColumn, endLineNumber, endColumn);
			if (!deleteSelection.isEmpty()) {
				let resultSelection;
				if (selection.isEmpty()) {
					edits.push(EditOperation.replace(deleteSelection, trimmedLinesContent));
					resultSelection = new Selection(deleteSelection.startLineNumber - lineOffset, trimmedLinesContent.length - columnDeltaOffset + 1, startLineNumber - lineOffset, trimmedLinesContent.length - columnDeltaOffset + 1);
				} else if (selection.startLineNumber === selection.endLineNumber) {
					edits.push(EditOperation.replace(deleteSelection, trimmedLinesContent));
					resultSelection = new Selection(selection.startLineNumber - lineOffset, selection.startColumn, selection.endLineNumber - lineOffset, selection.endColumn);
				} else {
					edits.push(EditOperation.replace(deleteSelection, trimmedLinesContent));
					resultSelection = new Selection(selection.startLineNumber - lineOffset, selection.startColumn, selection.startLineNumber - lineOffset, trimmedLinesContent.length - selectionEndPositionOffset);
				}
				if (Range.intersectRanges(deleteSelection, primaryCursor) !== null) endPrimaryCursor = resultSelection;
				else endCursorState.push(resultSelection);
			}
			lineOffset += deleteSelection.endLineNumber - deleteSelection.startLineNumber;
		}
		endCursorState.unshift(endPrimaryCursor);
		editor.pushUndoStop();
		editor.executeEdits(this.id, edits, endCursorState);
		editor.pushUndoStop();
	}
};
var TransposeAction = class extends EditorAction {
	constructor() {
		super({
			id: "editor.action.transpose",
			label: localize2(1333, "Transpose Characters around the Cursor"),
			precondition: EditorContextKeys.writable,
			canTriggerInlineEdits: true
		});
	}
	run(_accessor, editor) {
		const selections = editor.getSelections();
		if (selections === null) return;
		const model = editor.getModel();
		if (model === null) return;
		const commands = [];
		for (let i = 0, len = selections.length; i < len; i++) {
			const selection = selections[i];
			if (!selection.isEmpty()) continue;
			const cursor = selection.getStartPosition();
			const maxColumn = model.getLineMaxColumn(cursor.lineNumber);
			if (cursor.column >= maxColumn) {
				if (cursor.lineNumber === model.getLineCount()) continue;
				const deleteSelection = new Range(cursor.lineNumber, Math.max(1, cursor.column - 1), cursor.lineNumber + 1, 1);
				const chars = model.getValueInRange(deleteSelection).split("").reverse().join("");
				commands.push(new ReplaceCommand(new Selection(cursor.lineNumber, Math.max(1, cursor.column - 1), cursor.lineNumber + 1, 1), chars));
			} else {
				const deleteSelection = new Range(cursor.lineNumber, Math.max(1, cursor.column - 1), cursor.lineNumber, cursor.column + 1);
				const chars = model.getValueInRange(deleteSelection).split("").reverse().join("");
				commands.push(new ReplaceCommandThatPreservesSelection(deleteSelection, chars, new Selection(cursor.lineNumber, cursor.column + 1, cursor.lineNumber, cursor.column + 1)));
			}
		}
		editor.pushUndoStop();
		editor.executeCommands(this.id, commands);
		editor.pushUndoStop();
	}
};
var AbstractCaseAction = class extends EditorAction {
	run(_accessor, editor) {
		const selections = editor.getSelections();
		if (selections === null) return;
		const model = editor.getModel();
		if (model === null) return;
		const wordSeparators = editor.getOption(148);
		const textEdits = [];
		for (const selection of selections) if (selection.isEmpty()) {
			const cursor = selection.getStartPosition();
			const word = editor.getConfiguredWordAtPosition(cursor);
			if (!word) continue;
			const wordRange = new Range(cursor.lineNumber, word.startColumn, cursor.lineNumber, word.endColumn);
			const text = model.getValueInRange(wordRange);
			textEdits.push(EditOperation.replace(wordRange, this._modifyText(text, wordSeparators)));
		} else {
			const text = model.getValueInRange(selection);
			textEdits.push(EditOperation.replace(selection, this._modifyText(text, wordSeparators)));
		}
		editor.pushUndoStop();
		editor.executeEdits(this.id, textEdits);
		editor.pushUndoStop();
	}
};
